        goto done;
    }
    if (visible_needle && (!visible || !strstr(visible, visible_needle))) {
        rc = agent_selftest_fail(name, "visible text missing %s; got: %s",
                                 visible_needle,
                                 visible ? visible : "<null>");
        goto done;
    }
    printf("PASS stream:%s\n", name);

done:
