    agent_glm_tool_parse(p);
}

static bool agent_tool_parser_finish(agent_dsml_parser *p) {
    if (p && p->glm_native) {
        agent_glm_tool_parse(p);
        return p->state == AGENT_DSML_DONE;
    }
    return agent_dsml_finish(p);
}

