/* ---------- Global canvas setup ---------- */
const CV = document.getElementById("c");
const CTX = CV.getContext("2d");
CTX.imageSmoothingEnabled = false;
CTX.disableImageSmoothing = true;

// Scale canvas to fit screen while keeping pixels crisp.
function fitCanvas(){
  const sw = window.innerWidth, sh = window.innerHeight;
  const scale = Math.min(sw/320, sh/200) * 0.95;
  CV.style.width = Math.floor(320*scale)+"px";
  CV.style.height = Math.floor(200*scale)+"px";
}
window.addEventListener("resize", fitCanvas);
fitCanvas();

/* ---------- Commodore-inspired palette (16 colors) ---------- */
const PAL = [
  "#000000","#ffffff","#8d3a1f","#a5a5a5", // 0-3
  "#7f1f1f","#6d6d6d","#d77f7f","#d0a070", // 4-7
  "#d9a544","#b8a070","#5f9a5f","#3a7f3a", // 8-11
  "#1f6f3a","#a5d8a5","#5a5a9a","#a070a0"  // 12-15
];

/* ---------- Sprite drawing helper ---------- */
// sprite = array of strings, each char = hex digit 0-f palette index.
// transparent char = '.' (skip draw).
function drawSprite(spr, x, y, flip){
  CTX.save();
  if(flip){
    CTX.translate(x + spr[0].length, y);
    CTX.scale(-1,1);
    x = 0; y = 0;
  }
  for(let row=0; row<spr.length; row++){
    const line = spr[row];
    for(let col=0; col<line.length; col++){
      const c = line[col];
      if(c === '.') continue;
      const idx = parseInt(c,16);
      CTX.fillStyle = PAL[idx];
      CTX.fillRect(x+col, y+row, 1, 1);
    }
  }
  CTX.restore();
}

